// Four GTP transmitters for TMDS, around the Vivado gtwizard core gt_hdmi
// (generated by build.tcl: 0.7425 Gb/s, 148.5 MHz on REFCLK0 of quad 216,
// 20-bit words, no receivers, shared logic in the core). The core's own reset
// state machine brings the lanes up; ready = all four lanes done.
module hdmi_gtp (
    input  wire        sysclk,          // free-running, for the reset machines
    input  wire        reset,
    input  wire        refclk_p, refclk_n,
    input  wire [19:0] tx0, tx1, tx2, tx3,
    output wire        usrclk,          // 37.125 MHz, all lanes
    output wire        ready,
    output wire [3:0]  txp, txn
);
    wire [3:0] done;
    wire usr0, usr1, usr2, usr3;
    assign usrclk = usr0;
    assign ready  = &done;

    gt_hdmi core (
        .sysclk_in(sysclk),
        .soft_reset_tx_in(reset),
        .dont_reset_on_data_error_in(1'b1),
        .q0_clk0_gtrefclk_pad_p_in(refclk_p),
        .q0_clk0_gtrefclk_pad_n_in(refclk_n),
`define LANE(n, data, uclk) \
        .gt``n``_tx_fsm_reset_done_out(done[n]), .gt``n``_rx_fsm_reset_done_out(), \
        .gt``n``_data_valid_in(1'b1), \
        .gt``n``_txusrclk_out(uclk), .gt``n``_txusrclk2_out(), \
        .gt``n``_drpaddr_in(9'd0), .gt``n``_drpdi_in(16'd0), .gt``n``_drpdo_out(), \
        .gt``n``_drpen_in(1'b0), .gt``n``_drprdy_out(), .gt``n``_drpwe_in(1'b0), \
        .gt``n``_eyescanreset_in(1'b0), .gt``n``_eyescandataerror_out(), .gt``n``_eyescantrigger_in(1'b0), \
        .gt``n``_dmonitorout_out(), .gt``n``_gtrxreset_in(1'b0), .gt``n``_rxlpmreset_in(1'b0), \
        .gt``n``_gttxreset_in(1'b0), .gt``n``_txuserrdy_in(1'b1), \
        .gt``n``_txdata_in(data), \
        .gt``n``_gtptxn_out(txn[n]), .gt``n``_gtptxp_out(txp[n]), \
        .gt``n``_txoutclkfabric_out(), .gt``n``_txoutclkpcs_out(), .gt``n``_txresetdone_out(),
        `LANE(0, tx0, usr0)
        `LANE(1, tx1, usr1)
        `LANE(2, tx2, usr2)
        `LANE(3, tx3, usr3)
`undef LANE
        .gt0_pll0outclk_out(), .gt0_pll0outrefclk_out(), .gt0_pll0lock_out(),
        .gt0_pll0refclklost_out(), .gt0_pll1outclk_out(), .gt0_pll1outrefclk_out()
    );
endmodule
